from pathlib import Path

p=Path('index.html')
text=p.read_text()

old="""    // V1.22.7: first-pass FireBoard analysis using the already-imported samples.\n    const target = Number(state.target);\n    const sortedGroups = [...groups.entries()].sort((a, b) => (a[1].channel - b[1].channel) || String(a[1].deviceUuid || '').localeCompare(String(b[1].deviceUuid || '')));\n    const channelStats = sortedGroups.map(([sensorKey, group]) => {\n      const channel = group.channel;\n      const points = [...group.points].sort((a, b) => a.time - b.time);\n      const temps = points.map(point => point.temp);\n      const avg = temps.reduce((sum, value) => sum + value, 0) / Math.max(1, temps.length);\n      const avgAbsTargetError = Number.isFinite(target)\n        ? temps.reduce((sum, value) => sum + Math.abs(value - target), 0) / Math.max(1, temps.length)\n        : Number.POSITIVE_INFINITY;\n      return { sensorKey, channel, group, points, temps, avg, avgAbsTargetError };\n    });\n\n    let likelyPit = null;\n    if (Number.isFinite(target) && channelStats.length) {\n      const namedPit = channelStats.find(stat => /chamber|pit|ambient|grill|smoker/i.test(stat.group.label || ''));\n      likelyPit = namedPit || [...channelStats].sort((a, b) => a.avgAbsTargetError - b.avgAbsTargetError)[0];\n    }\n"""
new="""    // V1.26.0: analysis uses the user's explicit probe purpose. No label/temperature guessing.\n    const target = Number(state.target);\n    const sortedGroups = [...groups.entries()].sort((a, b) => (a[1].channel - b[1].channel) || String(a[1].deviceUuid || '').localeCompare(String(b[1].deviceUuid || '')));\n    const channelStats = sortedGroups.map(([sensorKey, group]) => {\n      const channel = group.channel;\n      const points = [...group.points].sort((a, b) => a.time - b.time);\n      const temps = points.map(point => point.temp);\n      const avg = temps.reduce((sum, value) => sum + value, 0) / Math.max(1, temps.length);\n      const assignment = probeRoles?.get(sensorKey) || {};\n      const roleType = assignment.role_type || '';\n      const cookRole = assignment.cook_role?.trim() || group.label;\n      return { sensorKey, channel, group, points, temps, avg, roleType, cookRole };\n    });\n\n    const chamberStats = channelStats.filter(stat => stat.roleType === 'chamber');\n    const foodStats = channelStats.filter(stat => stat.roleType === 'food');\n    const referenceStats = channelStats.filter(stat => stat.roleType === 'other');\n"""
if text.count(old)!=1: raise SystemExit('analysis classification anchor not found')
text=text.replace(old,new,1)

old="""    const analysisTitle = document.createElement('strong');\n    analysisTitle.textContent = 'FireBoard Analysis';\n    analysis.appendChild(analysisTitle);\n\n    const summary = document.createElement('div');\n    summary.className = 'sub';\n    summary.style.marginTop = '4px';\n    summary.textContent = Number.isFinite(target)\n      ? `Cook target: ${target.toFixed(0)}°F. Range timing below is based on the likely pit/chamber channel.`\n      : 'No numeric cook target is available, so target-range timing is not shown.';\n    analysis.appendChild(summary);\n\n    channelStats.forEach(stat => {\n      const row = document.createElement('div');\n      row.style.cssText = 'margin-top:9px;padding-top:9px;border-top:1px solid #2b2b2b;font-size:12px';\n      const min = Math.min(...stat.temps);\n      const max = Math.max(...stat.temps);\n      const unit = Number(stat.group.degree) === 1 ? 'C' : Number(stat.group.degree) === 2 ? 'F' : String(stat.group.degree || 'F');\n      const likelyText = likelyPit && stat.sensorKey === likelyPit.sensorKey ? ' — likely pit/chamber' : '';\n      row.textContent = `${stat.group.label}${likelyText}: avg ${stat.avg.toFixed(1)}°${unit}; min ${min.toFixed(1)}°; max ${max.toFixed(1)}°; ${stat.points.length} samples`;\n      analysis.appendChild(row);\n    });\n\n    if (likelyPit && Number.isFinite(target)) {\n      const within10 = weightedRangeDuration(likelyPit.points, 10);\n      const within25 = weightedRangeDuration(likelyPit.points, 25);\n      const stableAt = firstStablePeriod(likelyPit.points, 10);\n      const metrics = document.createElement('div');\n      metrics.style.cssText = 'display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px';\n      const metricData = [\n        ['Within ±10°F', within10.total ? `${formatDuration(within10.inRange)} (${Math.round(within10.inRange / within10.total * 100)}%)` : '—'],\n        ['Within ±25°F', within25.total ? `${formatDuration(within25.inRange)} (${Math.round(within25.inRange / within25.total * 100)}%)` : '—'],\n        ['10-min stable', stableAt ? formatTime(stableAt) : 'Not reached']\n      ];\n      metricData.forEach(([label, value]) => {\n        const box = document.createElement('div');\n        box.style.cssText = 'background:#202020;border:1px solid #303030;border-radius:9px;padding:8px';\n        const k = document.createElement('div');\n        k.style.cssText = 'font-size:10px;color:#999;text-transform:uppercase';\n        k.textContent = label;\n        const v = document.createElement('div');\n        v.style.cssText = 'font-size:14px;font-weight:700;margin-top:3px';\n        v.textContent = value;\n        box.appendChild(k); box.appendChild(v); metrics.appendChild(box);\n      });\n      analysis.appendChild(metrics);\n    }\n"""
new="""    const analysisTitle = document.createElement('strong');\n    analysisTitle.textContent = 'Purpose-aware FireBoard Analysis';\n    analysis.appendChild(analysisTitle);\n\n    const summary = document.createElement('div');\n    summary.className = 'sub';\n    summary.style.marginTop = '4px';\n    summary.textContent = `Using saved probe purposes: ${foodStats.length} food, ${chamberStats.length} smoker/chamber, ${referenceStats.length} reference. No sensor type is inferred from its label or temperature.`;\n    analysis.appendChild(summary);\n\n    foodStats.forEach(stat => {\n      const row = document.createElement('div');\n      row.style.cssText = 'margin-top:9px;padding-top:9px;border-top:1px solid #2b2b2b;font-size:12px';\n      const unit = Number(stat.group.degree) === 1 ? 'C' : Number(stat.group.degree) === 2 ? 'F' : String(stat.group.degree || 'F');\n      const first = stat.points[0]?.temp, latest = stat.points[stat.points.length-1]?.temp, peak = Math.max(...stat.temps);\n      const rise = Number.isFinite(first) && Number.isFinite(latest) ? latest-first : NaN;\n      row.textContent = `Food — ${stat.cookRole}: current ${latest.toFixed(1)}°${unit}; peak ${peak.toFixed(1)}°; change ${rise>=0?'+':''}${rise.toFixed(1)}°; ${stat.points.length} samples`;\n      analysis.appendChild(row);\n    });\n\n    chamberStats.forEach(stat => {\n      const row = document.createElement('div');\n      row.style.cssText = 'margin-top:9px;padding-top:9px;border-top:1px solid #2b2b2b;font-size:12px';\n      const min = Math.min(...stat.temps), max = Math.max(...stat.temps);\n      const latest = stat.points[stat.points.length-1]?.temp;\n      const unit = Number(stat.group.degree) === 1 ? 'C' : Number(stat.group.degree) === 2 ? 'F' : String(stat.group.degree || 'F');\n      row.textContent = `Smoker / chamber — ${stat.cookRole}: current ${latest.toFixed(1)}°${unit}; avg ${stat.avg.toFixed(1)}°; range ${min.toFixed(1)}–${max.toFixed(1)}°; ${stat.points.length} samples`;\n      analysis.appendChild(row);\n\n      if (Number.isFinite(target)) {\n        const within10 = weightedRangeDuration(stat.points, 10);\n        const within25 = weightedRangeDuration(stat.points, 25);\n        const stableAt = firstStablePeriod(stat.points, 10);\n        const metrics = document.createElement('div');\n        metrics.style.cssText = 'display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:8px';\n        const metricData = [\n          ['Within ±10°F', within10.total ? `${formatDuration(within10.inRange)} (${Math.round(within10.inRange / within10.total * 100)}%)` : '—'],\n          ['Within ±25°F', within25.total ? `${formatDuration(within25.inRange)} (${Math.round(within25.inRange / within25.total * 100)}%)` : '—'],\n          ['10-min stable', stableAt ? formatTime(stableAt) : 'Not reached']\n        ];\n        metricData.forEach(([label, value]) => {\n          const box = document.createElement('div');\n          box.style.cssText = 'background:#202020;border:1px solid #303030;border-radius:9px;padding:8px';\n          const k = document.createElement('div');\n          k.style.cssText = 'font-size:10px;color:#999;text-transform:uppercase';\n          k.textContent = label;\n          const v = document.createElement('div');\n          v.style.cssText = 'font-size:14px;font-weight:700;margin-top:3px';\n          v.textContent = value;\n          box.appendChild(k); box.appendChild(v); metrics.appendChild(box);\n        });\n        analysis.appendChild(metrics);\n      }\n    });\n\n    if (!foodStats.length && !chamberStats.length) {\n      const note=document.createElement('div');\n      note.className='sub'; note.style.marginTop='8px';\n      note.textContent='Assign Food or Smoker / chamber purposes to enable temperature analysis.';\n      analysis.appendChild(note);\n    }\n"""
if text.count(old)!=1: raise SystemExit('analysis UI anchor not found')
text=text.replace(old,new,1)

for old,new in [
("  document.title = 'LDCookLog Mobile V1.25.0';","  document.title = 'LDCookLog Mobile V1.26.0';"),
("  if (headerSub) headerSub.textContent = 'V1.25.0 Stateful BBQ Control Panel';","  if (headerSub) headerSub.textContent = 'V1.26.0 Stateful BBQ Control Panel';"),
("  if (footer) footer.innerHTML = 'V1.25.0 adds a user-selected sensor purpose (Food, Smoker / chamber, or Other / reference) to each cook-specific FireBoard probe assignment so later analysis can distinguish food temperatures from pit temperatures without guessing.<br><strong>Build 2026-09-14G</strong>';","  if (footer) footer.innerHTML = 'V1.26.0 makes FireBoard analysis purpose-aware: Food and Smoker / chamber streams are analyzed separately using the user-selected purpose, with no label or temperature guessing. Other / reference streams remain stored but are excluded from cook metrics.<br><strong>Build 2026-09-14H</strong>';"),
]:
    if text.count(old)!=1: raise SystemExit('version anchor not found')
    text=text.replace(old,new,1)

p.write_text(text)

swp=Path('service-worker.js'); sw=swp.read_text(); old="const CACHE_NAME = 'ldcooklog-v1-25-0';"; new="const CACHE_NAME = 'ldcooklog-v1-26-0';"
if sw.count(old)!=1: raise SystemExit('cache anchor not found')
swp.write_text(sw.replace(old,new,1))
print('V1.26.0 purpose-aware analysis patch applied successfully.')
